// Mini supervised rule (bukan ML library), tapi konsepnya mirip: data → aturan → prediksi
// Aturan contoh: jika tinggi > 5 dan lebar > 3 maka "A" else "B"

const tinggi = 7; // coba ganti 2..10
const lebar = 4; // coba ganti 1..8

let kelas;
if (tinggi > 5 && lebar > 3) {
  kelas = "A";
} else {
  kelas = "B";
}

console.log("Input: tinggi=" + tinggi + ", lebar=" + lebar);
console.log("Prediksi kelas = " + kelas);

// K-Means mini untuk konsep Unsupervised: data tanpa label → cari pola/kelompok
// Output: centroid akhir dan cluster tiap titik

const points = [
  { x: 1, y: 1 }, { x: 1, y: 2 }, { x: 2, y: 1 },
  { x: 8, y: 8 }, { x: 8, y: 9 }, { x: 9, y: 8 }
];

const k = 2;
const iterations = 6;

function dist(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.sqrt(dx * dx + dy * dy);
}

// init centroid: ambil dua titik pertama
let centroids = [ { ...points[0] }, { ...points[3] } ];

for (let it = 0; it < iterations; it++) {
  // assign
  const clusters = Array.from({ length: k }, () => []);
  for (const p of points) {
    const d0 = dist(p, centroids[0]);
    const d1 = dist(p, centroids[1]);
    const idx = d0 <= d1 ? 0 : 1;
    clusters[idx].push(p);
  }

  // update
  centroids = centroids.map((c, idx) => {
    const arr = clusters[idx];
    if (arr.length === 0) return c;
    const meanX = arr.reduce((s, p) => s + p.x, 0) / arr.length;
    const meanY = arr.reduce((s, p) => s + p.y, 0) / arr.length;
    return { x: meanX, y: meanY };
  });
}

// final assignment untuk tampilkan cluster
const clustersFinal = Array.from({ length: k }, () => []);
for (const p of points) {
  const idx = dist(p, centroids[0]) <= dist(p, centroids[1]) ? 0 : 1;
  clustersFinal[idx].push(p);
}

console.log("Centroids akhir:");
centroids.forEach((c, i) => console.log("  C" + i + " = (" + c.x.toFixed(2) + ", " + c.y.toFixed(2) + ")"));

console.log("Titik per cluster:");
clustersFinal.forEach((arr, i) => {
  const list = arr.map(p => "(" + p.x + "," + p.y + ")").join(" ");
  console.log("  Cluster " + i + ": " + list);
});
